#!/usr/bin/env python3
"""Модель выбирается под ЗАДАЧУ, и выбор либо доезжает, либо назван вслух.

Откуда это взялось. Модель у агента была свойством РОЛИ: исполнитель — средний
тир, советчики — свой. Размер и риск задачи на выбор не влияли вообще, и правка
на две строки уезжала той же моделью, что переписывание схемы данных. Дорогое не
тратилось там, где ошибка стоит переделки, и тратилось там, где хватило бы
дешёвого. Мерить раскладку по тирам система уже умела — решать не умела.

Что здесь заперто:

  · механическая правка (один файл, без требований) уходит на ДЕШЁВЫЙ тир;
  · задача, чью зону накрывает архитектурное решение, — на ДОРОГОЙ;
  · повторный заход после провала проверки — на ДОРОГОЙ, причём счётчик берётся
    у самой проверки, а не заводится второй;
  · зона, где теряются данные человека, — на ДОРОГОЙ, и это перевешивает
    признак дешевизны: миграция в одном файле остаётся миграцией;
  · причина выбора ЗАПИСАНА в ход стройки и читается оттуда — иначе потом
    нечем ответить, окупился ли дорогой тир;
  · выбор до исполнителя не доезжает в трёх названных документацией случаях —
    версия ниже порога, включённый запрет на выбор модели субагента, старый
    порядок разрешения с переменной умолчания, — и об этом сказано словами с
    ненулевым кодом, а не тихо исполнено дешёвой моделью под видом дорогой;
  · версия хоста неизвестна — это «не смог проверить» (код 2), а не «доедет»;
  · обратный контроль: обычная задача идёт прежним тиром, разные задачи дают
    РАЗНЫЕ тиры (флот не съезжает целиком на один), а модели в файлах агентов
    маршрутизатор не трогает.

Окружение каждого запуска собирается с нуля: `HOME` внутрь temp, `PATH` пуст,
счётчик попыток проверки — в temp. Иначе «зелено» описывало бы машину, а не код.

Тест самодостаточен: только стандартная библиотека и сами инструменты.

  python3 -m pytest tests/external/test_model_routing.py -q
"""
from __future__ import annotations

import importlib.util
import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

РЕПО = Path(__file__).resolve().parents[2]
ИНСТРУМЕНТЫ = РЕПО / "plugins" / "superstack" / "tools"
МАРШРУТ = ИНСТРУМЕНТЫ / "model_route.py"
АГЕНТЫ = РЕПО / "plugins" / "superstack" / "agents"

#: Порог, ниже которого поле модели у субагента не действует. Берётся у пробы,
#: а не переписывается сюда числом: разойдясь, тест и код спорили бы о том,
#: какой порог настоящий, и выиграл бы тот, кого не читают.
ПРОБА = ИНСТРУМЕНТЫ / "probe" / "collect.py"


def _загрузить(имя: str, путь: Path):
    спек = importlib.util.spec_from_file_location(имя, путь)
    мод = importlib.util.module_from_spec(спек)
    sys.modules[имя] = мод
    спек.loader.exec_module(мод)
    return мод


маршрут = _загрузить("ss_a17_route", МАРШРУТ)
проба = _загрузить("ss_a17_probe", ПРОБА)

ПОРОГ = ".".join(str(x) for x in проба.MODEL_ROUTING_FLOOR)
НИЖЕ_ПОРОГА = "2.1.42"


def модель_агента(имя: str) -> "str | None":
    """Модель, объявленная в шапке файла агента.

    Читается ШАПКА, а не первые полкилобайта: длина описания к делу не
    относится, и тест, спотыкающийся об неё, ловил бы не то, о чём написан.
    """
    текст = (АГЕНТЫ / f"{имя}.md").read_text(encoding="utf-8")
    куски = текст.split("---")
    шапка = куски[1] if len(куски) > 2 else ""
    for строка in шапка.splitlines():
        if строка.startswith("model:"):
            return строка.split(":", 1)[1].strip()
    return None


def задача(tid: str, **поля) -> dict:
    """Строка плана в том виде, в каком её пишет ход стройки."""
    т = {"id": tid, "name": f"задача {tid}", "status": "waiting"}
    т.update(поля)
    return т


class База(unittest.TestCase):
    """Общая оснастка: проект с ходом стройки и запуск инструмента."""

    def setUp(self):
        self.врем = tempfile.TemporaryDirectory()
        корень = Path(self.врем.name)
        self.дом = корень / "дом"
        self.проект = корень / "проект"
        (self.проект / ".superstack").mkdir(parents=True)
        self.дом.mkdir()
        self.состояние = self.проект / ".superstack" / "state.json"
        self.попытки = корень / "verify-attempts.json"
        self.addCleanup(self.врем.cleanup)

    # ---- подготовка ---------------------------------------------------
    def ход_стройки(self, *задачи) -> Path:
        self.состояние.write_text(json.dumps(
            {"schema": "superstack.progress.v1", "project": "проверка",
             "waves": {"1": list(задачи)}}, ensure_ascii=False),
            encoding="utf-8")
        return self.состояние

    def решение(self, зона: list, статус: str = "accepted") -> Path:
        """Архитектурное решение, накрывающее зону."""
        каталог = self.проект / "docs" / "adr"
        каталог.mkdir(parents=True, exist_ok=True)
        зоны = ", ".join(зона)
        # Имя по правилу читателя решений: четыре цифры и латиница.
        (каталог / "0001-one-queue.md").write_text(
            f"---\nzone: [{зоны}]\nstatus: {статус}\n---\n\n"
            "Очередь одна на весь сервис. Второй не заводить.\n",
            encoding="utf-8")
        return каталог

    def провал_проверки(self, сколько: int) -> None:
        """Столько подряд идущих провалов записала проверка этому проекту."""
        self.попытки.write_text(json.dumps(
            {str(self.проект.resolve()): {"attempt": сколько, "sig": "тесты"}}),
            encoding="utf-8")

    # ---- запуск -------------------------------------------------------
    def запустить(self, *аргументы, силой: str = None, умолчание: str = None
                  ) -> subprocess.CompletedProcess:
        среда = {
            "HOME": str(self.дом),
            "PATH": "",
            "PYTHONUTF8": "1",
            "PYTHONIOENCODING": "utf-8",
            "SUPERSTACK_IGNORE_PAUSE": "1",
            "SUPERSTACK_VERIFY_STATE": str(self.попытки),
        }
        if силой is not None:
            среда[маршрут.СИЛОЙ] = силой
        if умолчание is not None:
            среда[маршрут.УМОЛЧАНИЕ] = умолчание
        return subprocess.run([sys.executable, str(МАРШРУТ), *аргументы],
                              env=среда, capture_output=True, text=True,
                              timeout=300, cwd=str(self.проект))

    def маршрутизировать(self, *аргументы, версия: str = ПОРОГ,
                         силой: str = None, умолчание: str = None,
                         ожидаем: int = 0) -> dict:
        аргс = [str(self.состояние), *аргументы, "--json",
                "--now", "2026-09-08T03:00:00+00:00"]
        if версия is not None:
            аргс += ["--host-version", версия]
        p = self.запустить(*аргс, силой=силой, умолчание=умолчание)
        self.assertEqual(p.returncode, ожидаем,
                         f"код {p.returncode}\n{p.stderr[-900:]}")
        self.последний = p
        return json.loads(p.stdout)

    def журнал(self) -> list:
        данные = json.loads(self.состояние.read_text(encoding="utf-8"))
        return данные.get(маршрут.ЖУРНАЛ) or []


# ==========================================================================
# дешёвое — механическому
# ==========================================================================
class Механическое(База):

    def test_один_файл_без_требований_уходит_на_дешёвый_тир(self):
        self.ход_стройки(задача("01", zone=["src/ui/Button.tsx"]))
        v = self.маршрутизировать("01")
        self.assertEqual(v["tier"], маршрут.ДЕШЁВЫЙ, v)

    def test_причина_дешевизны_названа_а_не_подразумевается(self):
        self.ход_стройки(задача("01", zone=["src/ui/Button.tsx"]))
        v = self.маршрутизировать("01")
        self.assertTrue(v["why"].strip(), v)
        self.assertTrue(any("механич" in (с["признак"] + с["почему"]).lower()
                            for с in v["signals"]), v)

    def test_каталог_в_зоне_не_считается_одним_файлом(self):
        # Каталог — это неизвестное число файлов: удешевлять по нему значит
        # звать дешёвый тир на всё, что назвали папкой.
        self.ход_стройки(задача("01", zone=["src/ui/"]))
        v = self.маршрутизировать("01")
        self.assertEqual(v["tier"], маршрут.ОБЫЧНЫЙ, v)

    def test_требование_на_задаче_снимает_дешевизну(self):
        self.ход_стройки(задача("01", zone=["src/ui/Button.tsx"],
                                requirements=["R04"]))
        v = self.маршрутизировать("01")
        self.assertEqual(v["tier"], маршрут.ОБЫЧНЫЙ, v)


# ==========================================================================
# дорогое — туда, где ошибка дорого стоит
# ==========================================================================
class Дорогое(База):

    def test_задача_под_архитектурным_решением_уходит_на_дорогой_тир(self):
        self.ход_стройки(задача("02", zone=["src/bot/"],
                                requirements=["R01"]))
        adr = self.решение(["src/bot/"])
        v = self.маршрутизировать("02", "--adr", str(adr))
        self.assertEqual(v["tier"], маршрут.ДОРОГОЙ, v)
        self.assertTrue(any("решени" in с["признак"] for с in v["signals"]), v)

    def test_отменённое_решение_зону_не_накрывает(self):
        # Обратный контроль признака: дорогой тир обязан включаться от
        # ДЕЙСТВУЮЩЕГО решения, а не от наличия папки с файлами.
        self.ход_стройки(задача("02", zone=["src/bot/"],
                                requirements=["R01"]))
        adr = self.решение(["src/bot/"], статус="superseded")
        v = self.маршрутизировать("02", "--adr", str(adr))
        self.assertEqual(v["tier"], маршрут.ОБЫЧНЫЙ, v)

    def test_решение_о_чужой_зоне_на_выбор_не_влияет(self):
        self.ход_стройки(задача("02", zone=["src/web/"],
                                requirements=["R01"]))
        adr = self.решение(["src/bot/"])
        v = self.маршрутизировать("02", "--adr", str(adr))
        self.assertEqual(v["tier"], маршрут.ОБЫЧНЫЙ, v)

    def test_повторный_заход_уходит_на_дорогой_тир(self):
        self.ход_стройки(задача("03", zone=["src/web/"],
                                requirements=["R02"]))
        v = self.маршрутизировать("03", "--attempt", "2")
        self.assertEqual(v["tier"], маршрут.ДОРОГОЙ, v)
        self.assertTrue(any("заход" in с["признак"] or "повтор" in с["признак"]
                            for с in v["signals"]), v)

    def test_счётчик_попыток_берётся_у_проверки_а_не_заводится_второй(self):
        # Проверка уже записала провал этого проекта. Значит следующая раздача
        # той же работы — второй заход, и спрашивать об этом человека нечего.
        self.ход_стройки(задача("03", zone=["src/web/"],
                                requirements=["R02"]))
        self.провал_проверки(1)
        v = self.маршрутизировать("03")
        self.assertEqual(v["tier"], маршрут.ДОРОГОЙ, v)
        self.assertEqual(v["attempt"], 2, v)

    def test_без_провалов_заход_первый(self):
        self.ход_стройки(задача("03", zone=["src/web/"],
                                requirements=["R02"]))
        v = self.маршрутизировать("03")
        self.assertEqual(v["attempt"], 1, v)
        self.assertEqual(v["tier"], маршрут.ОБЫЧНЫЙ, v)

    def test_зона_потери_данных_перевешивает_дешевизну(self):
        # Один файл и ни одного требования — по форме механическая правка.
        # По существу — миграция: у кода откат git, у данных его нет.
        self.ход_стройки(задача("04", zone=["migrations/0007_drop.py"]))
        v = self.маршрутизировать("04")
        self.assertEqual(v["tier"], маршрут.ДОРОГОЙ, v)
        self.assertTrue(any("данн" in с["признак"] for с in v["signals"]), v)


# ==========================================================================
# причина видна
# ==========================================================================
class ПричинаЗаписана(База):

    def test_выбор_и_причина_ложатся_в_ход_стройки(self):
        self.ход_стройки(задача("05", zone=["src/ui/Button.tsx"]))
        v = self.маршрутизировать("05")
        записи = self.журнал()
        self.assertEqual(len(записи), 1, записи)
        з = записи[0]
        self.assertEqual(з["task"], "05", з)
        self.assertEqual(з["tier"], v["tier"], з)
        self.assertTrue(з["why"].strip(), з)
        self.assertTrue(з["signals"], з)
        self.assertEqual(з["at"], "2026-09-08T03:00:00+00:00", з)
        self.assertIn("delivery", з)

    def test_второй_заход_дописывается_а_не_затирает_первый(self):
        # Проверить, окупился ли дорогой тир, можно только по ИСТОРИИ выборов:
        # затёртый первый выбор превращает журнал в снимок последнего.
        self.ход_стройки(задача("05", zone=["src/web/"], requirements=["R02"]))
        self.маршрутизировать("05")
        self.маршрутизировать("05", "--attempt", "2")
        записи = self.журнал()
        self.assertEqual([з["tier"] for з in записи],
                         [маршрут.ОБЫЧНЫЙ, маршрут.ДОРОГОЙ], записи)

    def test_ход_стройки_переживает_запись_выбора(self):
        self.ход_стройки(задача("05", zone=["src/ui/Button.tsx"],
                                goal="кнопка отправляет форму"))
        self.маршрутизировать("05")
        данные = json.loads(self.состояние.read_text(encoding="utf-8"))
        строка = данные["waves"]["1"][0]
        self.assertEqual(строка["goal"], "кнопка отправляет форму", данные)
        self.assertEqual(данные["schema"], "superstack.progress.v1", данные)

    def test_сухой_прогон_ничего_не_пишет(self):
        self.ход_стройки(задача("05", zone=["src/ui/Button.tsx"]))
        v = self.маршрутизировать("05", "--dry-run")
        self.assertFalse(v["recorded"], v)
        self.assertEqual(self.журнал(), [])


# ==========================================================================
# доставка выбора до исполнителя
# ==========================================================================
class Доставка(База):

    def test_ниже_порога_версии_отказ_вслух_а_не_тихая_подмена(self):
        self.ход_стройки(задача("06", zone=["src/bot/"],
                                requirements=["R01"]))
        adr = self.решение(["src/bot/"])
        v = self.маршрутизировать("06", "--adr", str(adr),
                                  версия=НИЖЕ_ПОРОГА, ожидаем=1)
        self.assertEqual(v["delivery"]["состояние"], маршрут.НЕ_ДОЕДЕТ, v)
        # Тир назван честно, а не подменён на тот, который всё равно приедет.
        self.assertEqual(v["tier"], маршрут.ДОРОГОЙ, v)
        сказано = self.последний.stderr
        self.assertIn(ПОРОГ, сказано)
        self.assertIn(НИЖЕ_ПОРОГА, сказано)

    def test_отказ_доставки_тоже_записан_в_ход_стройки(self):
        self.ход_стройки(задача("06", zone=["src/ui/Button.tsx"]))
        self.маршрутизировать("06", версия=НИЖЕ_ПОРОГА, ожидаем=1)
        записи = self.журнал()
        self.assertEqual(записи[0]["delivery"]["состояние"],
                         маршрут.НЕ_ДОЕДЕТ, записи)

    def test_запрет_хоста_на_модель_субагента_тоже_не_доезжает(self):
        # Хост, которому велено гнать всех субагентов одной моделью, поле
        # модели игнорирует — и выбор не доезжает даже на свежей версии.
        self.ход_стройки(задача("06", zone=["src/ui/Button.tsx"]))
        v = self.маршрутизировать("06", силой="1", ожидаем=1)
        self.assertEqual(v["delivery"]["состояние"], маршрут.НЕ_ДОЕДЕТ, v)
        self.assertIn(маршрут.СИЛОЙ, self.последний.stderr)

    def test_на_старом_порядке_переменная_перекрывает_вызов(self):
        # Версия выше порога — поле модели работает, — но порядок ещё обратный:
        # переменная умолчания идёт раньше и вызова, и файла агента.
        self.ход_стройки(задача("06", zone=["src/ui/Button.tsx"]))
        v = self.маршрутизировать("06", версия="2.1.200", умолчание="haiku",
                                  ожидаем=1)
        self.assertEqual(v["delivery"]["состояние"], маршрут.НЕ_ДОЕДЕТ, v)
        self.assertIn(маршрут.УМОЛЧАНИЕ, self.последний.stderr)

    def test_на_старом_порядке_без_переменной_выбор_доезжает(self):
        self.ход_стройки(задача("06", zone=["src/ui/Button.tsx"]))
        v = self.маршрутизировать("06", версия="2.1.200")
        self.assertEqual(v["delivery"]["состояние"], маршрут.ДОЕДЕТ, v)

    def test_на_новом_порядке_переменная_вызову_не_мешает(self):
        self.ход_стройки(задача("06", zone=["src/ui/Button.tsx"]))
        v = self.маршрутизировать("06", версия="2.4.1", умолчание="haiku")
        self.assertEqual(v["delivery"]["состояние"], маршрут.ДОЕДЕТ, v)

    def test_выключенный_запрет_доставке_не_мешает(self):
        self.ход_стройки(задача("06", zone=["src/ui/Button.tsx"]))
        v = self.маршрутизировать("06", силой="0")
        self.assertEqual(v["delivery"]["состояние"], маршрут.ДОЕДЕТ, v)

    def test_версия_неизвестна_это_не_смог_а_не_доедет(self):
        self.ход_стройки(задача("06", zone=["src/ui/Button.tsx"]))
        v = self.маршрутизировать("06", версия=None, ожидаем=2)
        self.assertEqual(v["delivery"]["состояние"], маршрут.НЕИЗВЕСТНО, v)
        self.assertEqual(v["status"], "unknown", v)

    def test_на_пороге_версии_выбор_доезжает(self):
        self.ход_стройки(задача("06", zone=["src/ui/Button.tsx"]))
        v = self.маршрутизировать("06", версия=ПОРОГ)
        self.assertEqual(v["delivery"]["состояние"], маршрут.ДОЕДЕТ, v)
        self.assertEqual(v["status"], "pass", v)

    def test_факты_осмотра_подхватываются_сами(self):
        # Человек уже смотрел на свою машину — спрашивать его второй раз о том
        # же не о чем: файл фактов лежит на известном месте.
        self.ход_стройки(задача("06", zone=["src/ui/Button.tsx"]))
        куда = self.дом / ".claude" / "superstack" / "run"
        куда.mkdir(parents=True)
        (куда / "facts.json").write_text(json.dumps(
            {"rt.subagent_model_routing": {"value": True},
             "rt.active_version": {"value": "2.4.1"}}, ensure_ascii=False),
            encoding="utf-8")
        v = self.маршрутизировать("06", версия=None)
        self.assertEqual(v["delivery"]["состояние"], маршрут.ДОЕДЕТ, v)
        self.assertIn("2.4.1", v["delivery"]["почему"], v)

    def test_ответ_осмотра_принимается_как_готовый_вердикт(self):
        # Осмотр уже считает этот факт по своей же версии порога. Второй
        # счёт по той же величине разошёлся бы с первым при первой правке.
        self.ход_стройки(задача("06", zone=["src/ui/Button.tsx"]))
        факты = self.проект / "facts.json"
        факты.write_text(json.dumps(
            {"rt.subagent_model_routing": {"value": False},
             "rt.active_version": {"value": "2.1.99"}}, ensure_ascii=False),
            encoding="utf-8")
        v = self.маршрутизировать("06", "--facts", str(факты),
                                  версия=None, ожидаем=1)
        self.assertEqual(v["delivery"]["состояние"], маршрут.НЕ_ДОЕДЕТ, v)


# ==========================================================================
# обратный контроль
# ==========================================================================
class Прежнее(База):

    def test_обычная_задача_идёт_прежним_тиром(self):
        self.ход_стройки(задача("07", zone=["src/web/", "src/api/"],
                                requirements=["R01", "R02"]))
        v = self.маршрутизировать("07")
        self.assertEqual(v["tier"], маршрут.ОБЫЧНЫЙ, v)

    def test_флот_не_съезжает_целиком_на_один_тир(self):
        # Маршрутизатор, отвечающий одно и то же, — это прежняя жёсткая
        # раскладка под другим именем, и стоит она дороже.
        self.ход_стройки(
            задача("01", zone=["src/ui/Button.tsx"]),
            задача("02", zone=["migrations/0007_drop.py"]),
            задача("03", zone=["src/web/", "src/api/"],
                   requirements=["R01", "R02"]))
        тиры = {т: self.маршрутизировать(т)["tier"]
                for т in ("01", "02", "03")}
        self.assertEqual(len(set(тиры.values())), 3, тиры)

    def test_роли_проверяющих_маршрутизатор_не_трогает(self):
        # Модель советчика выбрана по другому основанию — независимости
        # проверки от того, кто писал код, — и от размера задачи не зависит.
        for имя in ("second-opinion", "blind-acceptance"):
            self.assertEqual(модель_агента(имя), "fable", имя)
        # Умолчание исполнителя — средний тир: вызов без маршрутизации не имеет
        # права молча стать дорогим, иначе флот съезжает на верхний тир сам.
        self.assertEqual(модель_агента("builder"), маршрут.ОБЫЧНЫЙ)

    def test_нет_такой_задачи_ошибка_вызова(self):
        self.ход_стройки(задача("07", zone=["src/web/"]))
        p = self.запустить(str(self.состояние), "99", "--json")
        self.assertEqual(p.returncode, 3, p.stderr[-500:])

    def test_нет_хода_стройки_ошибка_вызова(self):
        p = self.запустить(str(self.проект / ".superstack" / "нет.json"),
                           "01", "--json")
        self.assertEqual(p.returncode, 3, p.stderr[-500:])


# ==========================================================================
# разбор без запуска процесса
# ==========================================================================
class Признаки(unittest.TestCase):

    def test_дорогое_перевешивает_дешёвое(self):
        т = задача("01", zone=["migrations/0007_drop.py"])
        v = маршрут.решить(т, [], 1)
        self.assertEqual(v["tier"], маршрут.ДОРОГОЙ, v)
        self.assertTrue(маршрут.механическая(т), т)

    def test_признаки_перечислены_поимённо(self):
        т = задача("01", zone=["migrations/0007_drop.py"])
        v = маршрут.решить(т, [], маршрут.ПОВТОР)
        имена = {с["признак"] for с in v["signals"]}
        self.assertGreaterEqual(len(имена), 2, v)
        for с in v["signals"]:
            self.assertTrue(с["почему"].strip(), с)

    def test_пустая_задача_не_удешевляется_молча(self):
        # Ни зоны, ни требований — про такую задачу не известно ничего, и
        # «неизвестно» не повод звать дешёвый тир.
        v = маршрут.решить(задача("01"), [], 1)
        self.assertEqual(v["tier"], маршрут.ОБЫЧНЫЙ, v)


if __name__ == "__main__":
    unittest.main()
